-- Cadastro e plano operacional de treinamentos do RH.
-- Fonte inicial: aba Tarefas de PLANO DE TREINAMENTO_2027.xlsx (91 linhas).

create table if not exists public.rh_treinamentos (
  id uuid primary key default gen_random_uuid(),
  data_treinamento date not null,
  dia_semana text not null default '',
  semana text not null default '',
  tipo_planejamento text not null default 'P'
    check (tipo_planejamento in ('P', 'NP', 'RP')),
  treinamento text not null,
  turma_horario text not null default '',
  tipo_treinamento text not null default ''
    check (tipo_treinamento in ('', 'B', 'T.E', 'T.L')),
  data_eficacia date,
  realizado boolean not null default false,
  criado_por text references public.core_perfis(id),
  atualizado_por text references public.core_perfis(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  excluido_em timestamptz,
  excluido_por text references public.core_perfis(id),
  constraint rh_treinamentos_chave_unica unique (
    data_treinamento, treinamento, turma_horario, tipo_planejamento, tipo_treinamento
  )
);

create index if not exists rh_treinamentos_data_idx
  on public.rh_treinamentos (data_treinamento desc)
  where excluido_em is null;
create index if not exists rh_treinamentos_nome_idx
  on public.rh_treinamentos using btree (lower(treinamento))
  where excluido_em is null;

alter table public.rh_treinamentos enable row level security;

drop policy if exists rh_treinamentos_select on public.rh_treinamentos;
create policy rh_treinamentos_select on public.rh_treinamentos
  for select to authenticated
  using (true);

drop policy if exists rh_treinamentos_write on public.rh_treinamentos;
create policy rh_treinamentos_write on public.rh_treinamentos
  for all to authenticated
  using (public.pode_gerir_rh('rh_treinamentos'))
  with check (public.pode_gerir_rh('rh_treinamentos'));

grant select, insert, update, delete on table public.rh_treinamentos to authenticated;
grant all on table public.rh_treinamentos to service_role;

insert into public.rh_treinamentos (
  data_treinamento, dia_semana, semana, tipo_planejamento, treinamento,
  turma_horario, tipo_treinamento, data_eficacia, realizado
)
select
  s.data_treinamento::date,
  s.dia_semana,
  s.semana,
  s.tipo_planejamento,
  s.treinamento,
  s.turma_horario,
  s.tipo_treinamento,
  s.data_eficacia::date,
  s.realizado
